"""Assemble reviewed ImageGen poses and proven source aliases, art-review only."""
from pathlib import Path
from PIL import Image
import json,hashlib,subprocess,shutil
P=Path(__file__).resolve().parents[1];G='/opt/homebrew/bin/magick';O=P/'battle/frames';O.mkdir(exist_ok=True)
def run(*a):subprocess.run([G,*map(str,a)],check=True)
def info(p):return {'size':list(Image.open(p).size),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
selected={0:'candidate-keys-v1',10:'candidate-keys-v1',25:'candidate-keys-v1',**{i:'candidate-motion'for i in [1,2,3,4,5,6,8]},**{i:'candidate-revisions'for i in [7,9,11]},27:'candidate-special'}
records=[]
for f,d in selected.items():
 src=P/'battle'/d/f'frame-{f:03}.png';dst=O/f'frame-{f:03}.png';shutil.copy2(src,dst);subprocess.run(['/opt/homebrew/bin/oxipng','-o','4','--strip','safe',str(dst)],check=True,capture_output=True)
 r=next(r for r in json.loads((P/'battle'/d/'registration.json').read_text())if r['frame']==f);r.update({'source_frame':f,'path':f'frames/frame-{f:03}.png','status':'visual_review_pass',**info(dst)});records.append(r)
# Full source pose13 is pose0 shifted16 native pixels left; pose24 aliases13.
native0=Image.open(P/'reference/original-000.png').convert('RGBA');native13=Image.open(P/'reference/original-013.png').convert('RGBA');check=Image.new('RGBA',native0.size);check.alpha_composite(native0,(-16,0));assert check.tobytes()==native13.tobytes()
run('-size','320x256','xc:none',O/'frame-000.png','-geometry','-64+0','-compose','over','-composite',O/'frame-013.png')
shutil.copy2(O/'frame-013.png',O/'frame-024.png')
source_atlas=Image.open(P.parents[1]/json.loads((P/'reference/source-unit.json').read_text())['source_atlas']).convert('RGBA');native24=source_atlas.crop((8*80,64,9*80,128));assert native13.tobytes()==native24.tobytes()
for f in [13,24]:records.append({'source_frame':f,'representative_frame':0 if f==13 else 13,'translation':[-64,0]if f==13 else[0,0],'kind':'exact_native_RGBA_translation'if f==13 else'exact_native_RGBA_alias','path':f'frames/frame-{f:03}.png','status':'visual_review_pass',**info(O/f'frame-{f:03}.png')})
unit=json.loads((P/'reference/source-unit.json').read_text());required=unit['required_source_frames'];canonical=unit['unique_art_frames'];atlas=O/'baron-battle.png';run(*[O/f'frame-{f:03}.png'for f in canonical],'+append',atlas);subprocess.run(['/opt/homebrew/bin/oxipng','-o','4','--strip','safe',str(atlas)],check=True,capture_output=True)
mapping={'schema_version':1,'character_id':'enemy-baron','display_name':'敌方重甲兵（男爵）','original_class_id':22,'source_side':'enemy','status':'art_and_registration_verified','source_atlas':'../../../'+unit['source_atlas'],'source_atlas_base':'mapping directory','source_frame_size':[80,64],'output_frame_size':[320,256],'source_anchor':[40,64],'output_anchor':[160,256],'source_columns':16,'source_idle_frame':0,'canonical_frames':canonical,'independently_generated_drawings':14,'frame_mapping':{str(f):f'frames/frame-{f:03}.png'for f in required},'records':records,'variant_keys':unit['bound_action_keys'],'output_atlas':'frames/baron-battle.png','output_atlas_frame_order':canonical,'batches':[{'id':'all-battle','frames':canonical,'status':'visual_review_pass','review':'reviews/all-baron-original-new-dark.png'}],'source_semantics':{'0-9':'Foot heavy infantry; waist panels and trailing cloth cover parts of legs; not a third limb. One lance, blade lower-left, blunt butt upper-right.','1/7':'Original body rectangle[0,0,60,64] byte-identical; only trailing cloth differs. New7 derived by ImageGen cloth edit of new1.','10':'Shield edge extends left, lance prepared upper-right.','11':'Shallow upper-left lance thrust with bent elbow and wide planted stance.','25':'Overhead horizontal javelin preparation.','27':'Empty fist extends after release; real arm pose differs from idle.'},'art_mode':'Built-in imagegen, technical crop/uniform resampling/whole-body registration and proven translation aliases only.','runtime_integrated':False}
(P/'battle/frame_mapping.json').write_text(json.dumps(mapping,ensure_ascii=False,indent=2)+'\n')
refs=[]
for f in canonical:
 op=P/f'battle/candidate-revisions/source-review-{f:03}.png';run(P/f'reference/original-{f:03}.png','-filter','point','-resize','400%',op);refs.extend([op,O/f'frame-{f:03}.png'])
for c,l in [('#1d2932','dark'),('#eee8d8','light')]:run('montage','-font','/System/Library/Fonts/STHeiti Medium.ttc',*refs,'-tile','2x15','-geometry','320x256+0+6','-background',c,P/f'battle/reviews/all-baron-original-new-{l}.png')
qa={'status':'battle_art_review_pass','required_source_slots':16,'canonical_source_poses':15,'independent_drawings':14,'four_times_width_and_height':True,'source_alias_proofs':'0→13 fullRGBA translated−16 nativeX;13→24 fullRGBA exact; both asserted by bytes.','clipping_note':'Selected revised7/9/11 have zero out-of-canvas nonzero alpha. Earlier rejected11 with clipped lance is preserved only as draft.','registered_anchor_note':'Selected foot-span placement anchor is rounded; it does not assert all individual feet/joints exact.','known_visual_residuals':['Pose25 redesigned javelin is about136 output pixels wide vs source172; each endpoint is shorter16–20px; held overhead with unchanged hands/body.','Pose9 far boot stands about2 output pixels above near boot; silhouette and visible rear leg retained.','Helmet crest removed as part of authorized head redesign; hair top follows original underlying head at source y30, not crest y27.'],'weapon_and_occlusion_review':'Lower skirt panels and trailing cloth separated from legs;9 rear leg restored;11 elbow shortened into source envelope without moving body; single lance blade and blunt tail.','output_atlas':info(atlas),'atlas_quality_reason':'Lossless15-pose review atlas exceeds soft50KB reference to preserve armor seams and individual pose details. Separate frames optimized.','runtime_integrated':False}
(P/'battle/qa-summary.json').write_text(json.dumps(qa,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'required':16,'drawings':14,'atlas_bytes':atlas.stat().st_size,'frame_bytes_range':[min(r['bytes']for r in records),max(r['bytes']for r in records)]}))
